"""GPN-Star: preserve dataset versions, score construction and source reuse."""
def populate(c):
    e = c.ev('gpn-benchmarks','gpn-supp','Supplementary Methods, Evaluation Benchmarks, PDF pp. 12–17',
             'Defines human, mouse, fly, worm, chicken and Arabidopsis benchmarks, filters and controls.',url='https://static-content.springer.com/esm/art%3A10.1038%2Fs41586-026-11005-5/MediaObjects/41586_2026_11005_MOESM1_ESM.pdf#page=12')
    score = c.ev('gpn-scoring','gpn-supp','Supplementary Methods, Inference, PDF p. 10',
                 'Masked central-site LLR; absolute LLR for GWAS; entropy for heritability; average forward/reverse predictions.',url='https://static-content.springer.com/esm/art%3A10.1038%2Fs41586-026-11005-5/MediaObjects/41586_2026_11005_MOESM1_ESM.pdf#page=10')
    c.suite('gpn-evals','GPN-Star evaluations','Variant constraint, disease/trait variants, population variation, association analyses and annotation probes. Six reference species have separately trained models.',e,'gpn',status='partial',notes='Allele-frequency enrichment is a population-genetic proxy, not an experimental pathogenicity label. Human evaluation retains only variants scored by every compared model.')
    # Human tasks differ from other papers using the same upstream resource.
    specs = [
      ('clinvar','ClinVar 20220924','Missense pathogenicity','Pathogenic versus benign missense variants.','binary classification','Clinical annotations',('cds',),('variant-interpretation',),'auprc'),
      ('cosmic','COSMIC MutantCensus v98 + gnomAD','Recurrent cancer mutation status','Frequent COSMIC missense mutations (>0.1% of WGS/WES samples) versus common gnomAD missense variants.','binary classification','Cancer recurrence / population-frequency proxy',('cds',),('variant-interpretation','target-discovery'),'auprc'),
      ('proteingym','ProteinGym v0.1, 31 human assays','Experimental protein fitness','Restrict amino-acid substitutions to single-nucleotide-accessible changes. If multiple nucleotides encode the same substitution, select the most deleterious by CADD.','regression / ranking','Experimental DMS',('cds',),('protein-engineering','variant-interpretation'),'spearman'),
      ('hgmd','HGMD curated regulatory variants','Regulatory pathogenicity','Literature-curated pathogenic regulatory variants versus nine common controls per positive; match chromosome, consequence and distance to TSS.','binary classification','Curated disease association',('regulatory',),('variant-interpretation',),'auprc'),
      ('gwas-coding','GWAS fine-mapping, coding variants','Coding causal-variant prioritization','High versus low posterior inclusion probability; match controls on minor allele frequency. This differs from the noncoding TraitGym matching.','binary classification','Statistical fine-mapping proxy',('cds',),('target-discovery',),'auprc'),
    ]
    for slug, ds, target, desc, typ, labels, regions, apps, metric in specs:
        t='gpn-'+slug
        c.task(t,'gpn-evals',target,ds,target,desc,typ,labels,e,applications=apps,capabilities=('variant-effects',),regions=regions,populations=('human',),input='Variant-centered multispecies alignment and phylogenetic distances',limitations='Per-assay retained variant counts and exact common-score intersections remain to be audited.')
        p=c.protocol(t,t+'-llr','GPN-Star alignment-conditioned scoring',score,'zero-shot','Masked nucleotide probabilities / allele LLR','No downstream fitted head. Evaluation cohort is label-selected; this is not a held-out-species test. Pretraining validation chromosomes are a separate split.','variant / assay',metrics=(metric,),embeddings=False,notes='Context is 128 or 256 bp depending on alignment/model. ProteinGym nucleotide conversion uses CADD; record that auxiliary information.')
        c.use('gpnstar',t,e,'gpn',protocol=p)
        c.field('protocols',p,'split_rule',e)
    c.count('gpn-proteingym',31,'human protein assays',e,qualifier='Upstream assay panel, not number of variants or independent genes.')
    # Same dataset × target as TraitGym; a distinct GPN-Star protocol is linked.
    for task in ('traitgym-mendelian','traitgym-complex'):
        if task in c.ids['tasks']:
            c.member('gpn-evals',task,e,'GPN-Star explicitly reuses the processed TraitGym dataset. Matching and retained-score intersection are protocol-specific.')
            p=c.protocol(task,'gpn-'+task,'GPN-Star TraitGym scoring',score,'zero-shot','Alignment-conditioned masked LLR; absolute LLR for complex traits','Nine matched controls per positive. No downstream fitting; common-score intersection across compared models.','matched variant set',metrics=('auprc',),embeddings=False)
            c.use('gpnstar',task,e,'gpn',protocol=p)
    populations=[('human','gnomAD v3.1.2','Singletons versus MAF >5%'),('mouse','Wild Mouse Genome Project','Singletons versus allele frequency >0.2'),('fly','DEST, 24 August 2024','Allele frequency <0.002 versus >0.2; dataset has no singletons'),('worm','CaeNDR 20231213','Allele count 2 (one homozygous strain) versus allele frequency >0.2'),('chicken','Galbase GRCg6a','Allele frequency 0.001 (dataset minimum) versus >0.2'),('arabidopsis','1001 Genomes, GPN-processed','Singletons versus allele frequency >0.2')]
    for pop,ds,definition in populations:
        t='gpn-rare-'+pop
        c.task(t,'gpn-evals',ds+': rare-variant enrichment',ds,'Rare-variant enrichment in deleterious score tail',definition+'. Compare within consequence groups; human rare variants are subsampled to the common count in each group.','enrichment analysis','Population allele-frequency proxy',e,applications=('comparative-genomics','plant-breeding') if pop=='arabidopsis' else ('comparative-genomics',),capabilities=('evolutionary-inference','variant-effects'),regions=('genome',),populations=(pop,),input='SNV-centered alignment',output='Enrichment by score threshold and consequence',limitations='Frequency depends on demography and mutation rate as well as selection. Each species uses its own trained checkpoint; this does not establish transfer to an unseen species.')
        p=c.protocol(t,t+'-score','Rare/common score-tail analysis',e,'zero-shot','Alignment-conditioned variant LLR','Frequency-defined evaluation groups; no fitted readout. Human threshold permits 30 false discoveries. Do not assume every species uses an identical numerical threshold without code verification.','variant; consequence-stratified',metrics=('enrichment',),embeddings=False)
        c.use('gpnstar',t,e,'gpn',protocol=p)
    for slug,ds,pop,n,desc,regions in [
        ('mmrdb','Mouse Mutant Resource Database','mouse',470,'89 PCR-validated and 381 putatively pathogenic SNVs; lift GRCm38 to GRCm39 and exclude reference mismatches. Compare with common WMGP variants within retained consequence groups.',('cds','utr5','utr3','splice')),
        ('flybase','FlyBase FB2025_02','fly',2929,'Experimentally validated lethal missense, nonsense and splice SNVs; reference allele must match dm6. Common DEST variants are controls.',('cds','splice')),
        ('qin','Qin et al. experimental lethal variants','worm',72,'Experimentally validated lethal SNVs versus common CaeNDR controls in corresponding categories.',('genome',)),
    ]:
        t='gpn-'+slug
        c.task(t,'gpn-evals',ds+': damaging variants',ds,'Damaging versus common variant status',desc,'binary classification','Experimental / curated; putative labels explicitly retained for MMRdb',e,applications=('comparative-genomics','variant-interpretation') if pop=='mouse' else ('comparative-genomics',),capabilities=('variant-effects',),regions=regions,populations=(pop,),input='Variant-centered alignment',limitations='Count is the positive collection before all-model score intersection; negative count and final scored cohort remain unverified.')
        c.count(t,n,'positive SNVs',e,split='positive collection',qualifier='Before score-availability intersection.')
        p=c.protocol(t,t+'-score','Pathogenic/lethal variant ranking',e,'zero-shot','Alignment-conditioned masked variant LLR','Label-selected positives versus population-common controls; no fitted head.','variant',metrics=('auprc',),embeddings=False)
        c.use('gpnstar',t,e,'gpn',protocol=p)
    # Genome constraint and downstream association are different endpoints.
    e2=c.ev('gpn-association','gpn-supp','Heritability Enrichment Analysis and Rare Variant Association Testing, PDF pp. 18–22','S-LDSC uses 106 public GWAS traits with baselineLD v2.2; DeepRVAT uses UK Biobank and a separately defined training/evaluation phenotype partition.',url='https://static-content.springer.com/esm/art%3A10.1038%2Fs41586-026-11005-5/MediaObjects/41586_2026_11005_MOESM1_ESM.pdf#page=18')
    c.task('gpn-ldsc','gpn-evals','GWAS heritability enrichment','Public GWAS summary statistics / baselineLD v2.2','Heritability explained by score annotations','S-LDSC adjusts for baseline annotations. Top-score annotations and tissue-restricted annotations are compared across traits.','association / enrichment analysis','GWAS summary statistics',e2,applications=('target-discovery',),capabilities=('evolutionary-inference',),regions=('genome','regulatory'),populations=('human',),input='Genome-wide model scores and LD reference',output='Enrichment and standardized regression coefficient',limitations='Tissue annotations come from external SEG expression and cCRE data; they are not evidence that the unsupervised model directly predicts tissue-specific expression.')
    c.protocol('gpn-ldsc','gpn-ldsc-protocol','Stratified LD score regression',e2,'statistical analysis of pretrained scores','Entropy / quantile-binarized annotations with baselineLD covariates','106 unrestricted traits; block jackknife for uncertainty. This is neither a sequence-level train/test split nor held-out-species prediction.','GWAS trait / genomic jackknife block',metrics=('enrichment',),embeddings=False,fitted='S-LDSC regression coefficients',notes='Seven tissue analyses use external tissue-region masks. Score thresholds are set among common variants.')
    for value,unit in [(106,'GWAS traits'),(9997231,'reference variants'),(5961159,'common reference variants')]:c.count('gpn-ldsc',value,unit,e2)
    c.use('gpnstar','gpn-ldsc',e2,'gpn')
    c.task('gpn-rvat','gpn-evals','Rare-variant gene–phenotype association','UK Biobank / DeepRVAT v1.1','Significant gene–phenotype associations','Use model-derived annotations in DeepRVAT burden scores and association testing.','association analysis','Individual-level genotypes and phenotypes',e2,applications=('target-discovery',),capabilities=('variant-effects',),regions=('gene','cds'),populations=('human',),input='Rare variants, model scores, covariates and phenotypes',output='Significant gene–phenotype associations',limitations='UK Biobank individual-level data require access. This catalogue does not redistribute them.')
    c.protocol('gpn-rvat','gpn-rvat-protocol','DeepRVAT plus REGENIE',e2,'downstream supervised aggregation','Variant scores as annotations','21 training phenotypes; 34 evaluation phenotypes include 21 training and 13 new phenotypes. MAF filters differ between aggregation training (<1%) and association testing (<0.1%).','phenotype / participant',metrics=('discoveries',),embeddings=False,fitted='DeepRVAT aggregation model',notes='Three seeds; Bonferroni correction. Inspect participant partition and phenotype overlap before interpreting transfer.')
    c.count('gpn-rvat',161822,'unrelated European-ancestry participants',e2)
    c.use('gpnstar','gpn-rvat',e2,'gpn')
    e3=c.ev('gpn-annotation','gpn-supp','Supplementary Methods, Genomic Annotation Classification, PDF pp. 10–11','Ensembl 113 and ENCODE cCRE v4 labels; 100-bp windows, repeat exclusion, conserved/nonconserved balancing; logistic regression with leave-one-chromosome-out validation.',url='https://static-content.springer.com/esm/art%3A10.1038%2Fs41586-026-11005-5/MediaObjects/41586_2026_11005_MOESM1_ESM.pdf#page=10')
    c.task('gpn-annotation','gpn-evals','Functional-region classification','Ensembl 113 / ENCODE cCRE v4','Genomic annotation class','Use standardized, strand-averaged embeddings of annotated 100-bp windows. Repeat-overlapping windows are excluded.','classification','Reference annotations',e3,applications=('genome-annotation',),capabilities=('functional-prediction',),regions=('genome',),populations=('human',),input='100-bp labeled window embedded within 256-bp context',limitations='Class-specific task expansion and final per-class counts remain to be audited; this record covers the documented multiclass target.')
    c.protocol('gpn-annotation','gpn-annotation-probe','Chromosome-held-out annotation probe',e3,'frozen probe','Mean embedding of middle 100 bp; average forward/reverse; standardize', 'Leave one chromosome out; train on all other chromosomes.','chromosome',metrics=(),embeddings=True,fitted='Logistic regression; inverse-frequency class weights; default L2',notes='Up to 10,000 conserved + 10,000 nonconserved windows per class, plus 20,000 background windows. These are caps, not measured final counts.')
    c.use('gpnstar','gpn-annotation',e3,'gpn')
    c.finding(None,'GPN-Star is alignment-conditioned and uses species-specific trained models. Its six-species results must not be represented as a single model transferring to six unseen species.',score,suite='gpn-evals')
    c.finding(None,'The LDLR dependency-map analysis is recorded as an exploratory local case study; it does not establish performance on a general experimental genetic-interaction benchmark.',e3,suite='gpn-evals')
    for slug,ds,target,desc,regions,metric in [
        ('gnocchi','gnomAD Gnocchi v3 QC-passing windows','Agreement with population constraint','Downsample Gnocchi 1-kb windows to 100 per unit z-score bin, yielding 2,000 windows. Compare mean model score across all possible variants to Gnocchi z-score.',('genome',),'spearman'),
        ('ldlr','LDLR promoter MPRA','Agreement between dependency map and regulatory effect','Exploratory local dependency-map comparison. Retain variants with ≥10 barcodes and p<1e-5; average allelic effects per position, set unsupported positions to zero and smooth five adjacent positions.',('promoter','tfbs'),None),
    ]:
        t='gpn-'+slug
        c.task(t,'gpn-evals',target,ds,target,desc,'constraint diagnostic' if slug=='gnocchi' else 'mechanistic case study','Population constraint proxy' if slug=='gnocchi' else 'Experimental MPRA',e if slug=='gnocchi' else e3,applications=('comparative-genomics',) if slug=='gnocchi' else ('regulatory-engineering',),capabilities=('evolutionary-inference',) if slug=='gnocchi' else ('genetic-interactions',),regions=regions,populations=('human',),input='Genome-wide model scores / local dependency map',limitations='Gnocchi is not an independent experimental function measurement. A local dependency map does not establish broadly validated epistasis prediction.')
        c.protocol(t,t+'-protocol','GPN-Star diagnostic',e if slug=='gnocchi' else e3,'zero-shot diagnostic','Model probabilities / dependency perturbations','Source-selected diagnostic cohort; no fitted biological prediction head.','window / nucleotide position',metrics=(metric,) if metric else (),embeddings=False)
        c.use('gpnstar',t,e if slug=='gnocchi' else e3,'gpn')
    c.count('gpn-gnocchi',2000,'1-kb windows',e)
    rare=c.ev('gpn-rare-threshold','gpn-paper','Figure 5a legend','All five non-human rare-variant enrichment analyses choose a deleterious-score tail allowing 30 false discoveries.')
    for p in c.rows['protocols']:
        if p['id'].startswith('gpn-rare-'):
            p['split_rule']='Frequency-defined evaluation groups, stratified by consequence; no fitted readout. Deleterious-score threshold allows 30 false discoveries; definitions of rare/common vary by species.'
            c.field('protocols',p['id'],'split_rule',rare)
    # A model-derived dependency statistic is not measured pairwise epistasis.
    for r in c.rows['task_categories']:
        if r['task_id']=='gpn-ldlr' and r['category_id']=='genetic-interactions':
            r['relation']='exploratory diagnostic'
            r['rationale']='Model-derived local nucleotide dependency map compared to single-variant MPRA effects; no general experimental epistasis endpoint is established.'
    # Keep pretraining chromosome partitions separate from genome-wide VEP cohorts.
    es=c.code('gpn-human-pretraining-split','songlab-cal/gpn','analysis/gpn-star/train_and_eval/workflow/Snakefile_hg38','SPLIT_CHROMS =','Archived human alignment workflow declares train chr1–20/X/Y, validation chr21, test chr22; these are pretraining sequence partitions, not a claim that VEP labels are restricted to chr22.')
    c.field('models','gpnstar','pretraining_split',es)
    next(m for m in c.rows['models'] if m['id']=='gpnstar')['notes']='Archived hg38 workflow: train chr1–20/X/Y, validation chr21, test chr22. Model variants and species use distinct alignments. Genome-wide variant cohorts must not be relabeled as chr22-only evaluation.'
    ec=c.code('gpn-calibration-code','songlab-cal/gpn','analysis/gpn-star/train_and_eval/workflow/rules/vep.smk','rule get_llr_calibrated:','Released workflow subtracts pentanucleotide-specific neutral mean LLR; calibrated entropy divides by its neutral mean. Calibration is an additional resource/procedure.')
    c.field('models','gpnstar','score_calibration',ec)
    # These require individual source assay IDs before they meet the chosen task unit.
    next(r for r in c.rows['tasks'] if r['id']=='gpn-proteingym')['status']='panel-pending'
    gpnfig=c.ev('gpn-evo-comparison','gpn-paper','Figure 2 and Supplementary Methods, Compared models','GPN-Star compares Evo 2 7B/40B likelihood scores on human variant benchmarks; these are external evaluations of Evo 2.')
    for t in ('gpn-clinvar','gpn-cosmic','gpn-proteingym','gpn-hgmd','gpn-gwas-coding','traitgym-mendelian','traitgym-complex'):
        c.use('evo2',t,gpnfig,'gpn','external-evaluation',note='GPN-Star paper human benchmark; do not attribute to original Evo 2 paper.')
